// Mappe l'événement Supabase vers une ligne `notifications`.
const b = $json.body || $json;
const table = b.table || 'inconnu';
const rec = b.record || {};
let out = null;
switch (table) {
  case 'team_reviews':
    out = { audience: 'coach', player_id: null, kind: 'wellness', title: 'Nouveau ressenti équipe', body: rec.comment || '', link: '#team-reviews' };
    break;
  case 'convocation_responses':
    if ((rec.status || '').toLowerCase() !== 'absent') return [];
    out = { audience: 'coach', player_id: null, kind: 'absence', title: 'Absence signalée', body: `Joueuse ${rec.player_id}`, link: '#convoc/' + rec.convocation_id };
    break;
  case 'convocations':
    out = { audience: 'all', player_id: null, kind: 'convocation', title: 'Nouvelle convocation', body: rec.title || '', link: '#convoc/' + rec.id };
    break;
  case 'matches':
    out = { audience: 'all', player_id: null, kind: 'match', title: 'Nouveau match', body: rec.opponent || rec.title || '', link: '#match/' + rec.id };
    break;
  case 'training_plans':
    if (!(rec.plan && rec.plan.validated)) return [];
    out = { audience: 'all', player_id: null, kind: 'plan', title: "Plan d'entraînement validé", body: '', link: '#training/' + rec.id };
    break;
  default:
    return [];
}
return [{ json: out }];
